#include <bits/stdc++.h>
using namespace std;using ll=long long;
struct Node{int l=0,r=0,c=0;};vector<Node>t(1);int put(int v,int l,int r,int x){int u=t.size();t.push_back(t[v]);t[u].c++;if(r-l>1){int m=(l+r)/2;if(x<m){int z=put(t[u].l,l,m,x);t[u].l=z;}else{int z=put(t[u].r,m,r,x);t[u].r=z;}}return u;}int kth(int a,int b,int l,int r,int k){if(r-l==1)return l;int m=(l+r)/2;int c=t[t[b].l].c-t[t[a].l].c;if(k<=c)return kth(t[a].l,t[b].l,l,m,k);return kth(t[a].r,t[b].r,m,r,k-c);}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<ll>a(n);for(ll&x:a)cin>>x;auto vals=a;sort(vals.begin(),vals.end());vals.erase(unique(vals.begin(),vals.end()),vals.end());int z=vals.size();t.reserve(1+n*(bit_width((unsigned)z)+1));vector<int>roots(n+1);for(int i=0;i<n;i++)roots[i+1]=put(roots[i],0,z,lower_bound(vals.begin(),vals.end(),a[i])-vals.begin());while(q--){int l,r,k;cin>>l>>r>>k;cout<<vals[kth(roots[l],roots[r],0,z,k)]<<'\n';}}
